-- Stage 1D statements/reconciliation/close (BC-v2.1 mandatory gate 8).
create type public.reconciliation_status as enum('open','closed','reopened');
create type public.reconciliation_resolution as enum('matched_transaction','stale_balance','missing_event','duplicate','pending_posting','opening_balance','adjustment');
create type public.reconciliation_transition as enum('closed','reopened');
create table public.statements(id uuid primary key default gen_random_uuid(),household_id uuid not null references public.households(id),account_id uuid not null,period_start date not null,period_end date not null check(period_end>=period_start),opening_minor bigint not null,ending_minor bigint not null,currency char(3) not null check(currency=upper(currency)),source_hash text not null check(source_hash~'^[a-f0-9]{64}$'),created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),unique(household_id,id),unique(household_id,account_id,period_start,period_end,source_hash),constraint fk_statement_account_tenant foreign key(household_id,account_id)references public.accounts(household_id,id));
create table public.statement_lines(household_id uuid not null references public.households(id),id uuid not null default gen_random_uuid(),statement_id uuid not null,line_key text not null,line_date date not null,amount_minor bigint not null,description text not null check(length(description)between 1 and 500),created_at timestamptz not null default now(),primary key(household_id,id),unique(household_id,statement_id,line_key),constraint fk_statement_line_tenant foreign key(household_id,statement_id)references public.statements(household_id,id));
create table public.reconciliation_sessions(household_id uuid not null references public.households(id),id uuid not null default gen_random_uuid(),statement_id uuid not null,account_id uuid not null,ledger_ending_minor bigint not null,difference_minor bigint not null,status public.reconciliation_status not null,formula_version text not null,period_lock_id uuid,closed_by uuid not null references auth.users(id),closed_at timestamptz not null,reopened_at timestamptz,created_at timestamptz not null default now(),primary key(household_id,id),unique(household_id,statement_id),constraint fk_session_statement_tenant foreign key(household_id,statement_id)references public.statements(household_id,id),constraint fk_session_account_tenant foreign key(household_id,account_id)references public.accounts(household_id,id));
create table public.reconciliation_items(household_id uuid not null references public.households(id),id uuid not null default gen_random_uuid(),session_id uuid not null,statement_line_id uuid not null,resolution public.reconciliation_resolution not null,transaction_id uuid,explanation text not null check(length(explanation)between 1 and 500),created_at timestamptz not null default now(),primary key(household_id,id),unique(household_id,session_id,statement_line_id),constraint fk_item_session_tenant foreign key(household_id,session_id)references public.reconciliation_sessions(household_id,id),constraint fk_item_line_tenant foreign key(household_id,statement_line_id)references public.statement_lines(household_id,id),constraint fk_item_txn_tenant foreign key(household_id,transaction_id)references public.canonical_transactions(household_id,id));
create table public.reconciliation_adjustments(household_id uuid not null references public.households(id),id uuid not null default gen_random_uuid(),session_id uuid not null,kind public.reconciliation_resolution not null check(kind<>'matched_transaction'),amount_minor bigint not null,explanation text not null check(length(explanation)between 1 and 500),created_at timestamptz not null default now(),primary key(household_id,id),constraint fk_adjustment_session_tenant foreign key(household_id,session_id)references public.reconciliation_sessions(household_id,id));
create table public.close_checklists(household_id uuid not null references public.households(id),id uuid not null default gen_random_uuid(),session_id uuid not null,checklist_version text not null,checks jsonb not null check(jsonb_typeof(checks)='object'),created_at timestamptz not null default now(),primary key(household_id,id),unique(household_id,session_id),constraint fk_checklist_session_tenant foreign key(household_id,session_id)references public.reconciliation_sessions(household_id,id));
create table public.reconciliation_status_events(household_id uuid not null references public.households(id),id uuid not null default gen_random_uuid(),session_id uuid not null,transition public.reconciliation_transition not null,reason text,actor jsonb not null,command_id uuid not null,created_at timestamptz not null default now(),primary key(household_id,id),unique(household_id,session_id,command_id),constraint fk_reconciliation_event_tenant foreign key(household_id,session_id)references public.reconciliation_sessions(household_id,id));
alter table public.period_locks add constraint period_locks_household_id_id_key unique(household_id,id);alter table public.reconciliation_sessions add constraint fk_session_lock_tenant foreign key(household_id,period_lock_id)references public.period_locks(household_id,id);
create trigger statements_immutable before update or delete on public.statements for each row execute function public.keel_forbid_mutation();
create trigger statement_lines_immutable before update or delete on public.statement_lines for each row execute function public.keel_forbid_mutation();create trigger reconciliation_items_immutable before update or delete on public.reconciliation_items for each row execute function public.keel_forbid_mutation();create trigger reconciliation_adjustments_immutable before update or delete on public.reconciliation_adjustments for each row execute function public.keel_forbid_mutation();create trigger close_checklists_immutable before update or delete on public.close_checklists for each row execute function public.keel_forbid_mutation();create trigger reconciliation_events_immutable before update or delete on public.reconciliation_status_events for each row execute function public.keel_forbid_mutation();
create function public.keel_statement_access(p_household_id uuid,p_statement_id uuid,p_write boolean)returns boolean language sql security definer stable set search_path=public as $$select exists(select 1 from public.statements s where s.household_id=p_household_id and s.id=p_statement_id and public.keel_recurring_account_access(p_household_id,s.account_id,p_write))$$;
create function public.keel_statement_create(p_command_id uuid,p_economic_event_key text,p_actor jsonb,p_household_id uuid,p_payload jsonb)returns jsonb language plpgsql security definer set search_path=public as $$declare v_hash text:=public.keel_payload_hash(p_payload);v_replay jsonb;v_actor jsonb;v_statement uuid:=gen_random_uuid();v_line jsonb;v_account uuid;v_start date;v_period_end date;v_open bigint;v_end bigint;v_sum numeric;v_after jsonb;v_result jsonb;begin perform public.keel_assert_member_write(p_household_id);v_actor:=public.keel_actor_from_jwt();v_replay:=public.keel_idempotency_check(p_household_id,p_economic_event_key,v_hash);if v_replay is not null then return v_replay;end if;
if jsonb_typeof(p_payload)<>'object'or(p_payload-'account_id'-'period_start'-'period_end'-'opening_minor'-'ending_minor'-'currency'-'source_hash'-'lines')<>'{}'::jsonb or jsonb_typeof(p_payload->'lines')<>'array'or jsonb_array_length(p_payload->'lines')<1 or jsonb_array_length(p_payload->'lines')>5000 or coalesce(p_payload->>'opening_minor','')!~'^-?(0|[1-9][0-9]*)$'or p_payload->>'opening_minor'='-0'or coalesce(p_payload->>'ending_minor','')!~'^-?(0|[1-9][0-9]*)$'or p_payload->>'ending_minor'='-0'or coalesce(p_payload->>'currency','')!~'^[A-Z]{3}$'or coalesce(p_payload->>'source_hash','')!~'^[a-f0-9]{64}$'then raise exception'KEEL_INVALID_COMMAND: malformed statement'using errcode='P0009';end if;
begin v_account:=(p_payload->>'account_id')::uuid;v_start:=(p_payload->>'period_start')::date;v_period_end:=(p_payload->>'period_end')::date;v_open:=(p_payload->>'opening_minor')::bigint;v_end:=(p_payload->>'ending_minor')::bigint;if v_start>v_period_end then raise exception'bad';end if;exception when others then raise exception'KEEL_INVALID_COMMAND: invalid statement scalars'using errcode='P0009';end;
if not exists(select 1 from public.accounts a where a.household_id=p_household_id and a.id=v_account and a.currency=p_payload->>'currency')or not public.keel_recurring_account_access(p_household_id,v_account,true)then raise exception'KEEL_SCOPE_VIOLATION: account not found'using errcode='P0006';end if;
if(select count(*)<>count(distinct l->>'line_key')from jsonb_array_elements(p_payload->'lines')l)or exists(select 1 from jsonb_array_elements(p_payload->'lines')l where(l-'line_key'-'date'-'amount_minor'-'description')<>'{}'::jsonb or length(coalesce(l->>'line_key',''))not between 1 and 100 or coalesce(l->>'amount_minor','')!~'^-?(0|[1-9][0-9]*)$'or l->>'amount_minor'='-0'or length(coalesce(l->>'description',''))not between 1 and 500)then raise exception'KEEL_INVALID_COMMAND: invalid statement lines'using errcode='P0009';end if;
begin for v_line in select value from jsonb_array_elements(p_payload->'lines')loop if(v_line->>'date')::date not between v_start and v_period_end then raise exception'bad';end if;perform(v_line->>'amount_minor')::bigint;end loop;select sum((l->>'amount_minor')::bigint)::numeric into v_sum from jsonb_array_elements(p_payload->'lines')l;exception when others then raise exception'KEEL_INVALID_COMMAND: invalid statement line values'using errcode='P0009';end;
if v_open::numeric+v_sum<>v_end::numeric then raise exception'KEEL_INVALID_COMMAND: statement lines do not reconcile'using errcode='P0009';end if;
insert into public.statements(household_id,id,account_id,period_start,period_end,opening_minor,ending_minor,currency,source_hash,created_by)values(p_household_id,v_statement,v_account,v_start,v_period_end,v_open,v_end,p_payload->>'currency',p_payload->>'source_hash',(v_actor->>'userId')::uuid);
for v_line in select value from jsonb_array_elements(p_payload->'lines')loop insert into public.statement_lines(household_id,statement_id,line_key,line_date,amount_minor,description)values(p_household_id,v_statement,v_line->>'line_key',(v_line->>'date')::date,(v_line->>'amount_minor')::bigint,v_line->>'description');end loop;
v_after:=jsonb_build_object('statementId',v_statement,'status','open','openingMinor',v_open::text,'endingMinor',v_end::text);v_result:=jsonb_build_object('commandId',p_command_id,'economicEventKey',p_economic_event_key,'idempotentReplay',false,'effects',v_after,'asOf',to_char(now()at time zone'utc','YYYY-MM-DD"T"HH24:MI:SS"Z"'));perform public.keel_finish_command(p_command_id,'statements.create',p_economic_event_key,p_household_id,v_actor,v_hash,'statements.created','statement',v_statement,v_after,v_result);return v_result;exception when unique_violation then raise exception'KEEL_IDEMPOTENCY_CONFLICT: duplicate statement source'using errcode='P0007';end;$$;
create function public.keel_reconciliation_close(p_command_id uuid,p_economic_event_key text,p_actor jsonb,p_household_id uuid,p_payload jsonb)returns jsonb language plpgsql security definer set search_path=public as $$
declare v_hash text:=public.keel_payload_hash(p_payload);v_replay jsonb;v_actor jsonb;v_s public.statements%rowtype;v_session uuid:=gen_random_uuid();v_lock uuid;v_ledger bigint;v_diff bigint;v_adj bigint;v_item jsonb;v_row jsonb;v_entity uuid;v_after jsonb;v_result jsonb;
begin
 perform public.keel_assert_member_write(p_household_id);v_actor:=public.keel_actor_from_jwt();v_replay:=public.keel_idempotency_check(p_household_id,p_economic_event_key,v_hash);if v_replay is not null then return v_replay;end if;
 if jsonb_typeof(p_payload)<>'object'or(p_payload-'statement_id'-'items'-'adjustments')<>'{}'::jsonb or jsonb_typeof(p_payload->'items')<>'array'or jsonb_typeof(p_payload->'adjustments')<>'array'or jsonb_array_length(p_payload->'items')<1 or jsonb_array_length(p_payload->'items')>5000 or jsonb_array_length(p_payload->'adjustments')>100 then raise exception'KEEL_INVALID_COMMAND: malformed reconciliation close'using errcode='P0009';end if;
 begin perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(p_household_id::text||':'||(p_payload->>'statement_id'),0));select*into v_s from public.statements where household_id=p_household_id and id=(p_payload->>'statement_id')::uuid;exception when invalid_text_representation then raise exception'KEEL_INVALID_COMMAND: invalid statement id'using errcode='P0009';end;
 if not found or exists(select 1 from public.reconciliation_sessions r where r.household_id=p_household_id and r.statement_id=v_s.id)or not public.keel_statement_access(p_household_id,v_s.id,true)then raise exception'KEEL_SCOPE_VIOLATION: statement not found'using errcode='P0006';end if;
 if jsonb_array_length(p_payload->'items')<>(select count(*)from public.statement_lines where household_id=p_household_id and statement_id=v_s.id)or(select count(*)<>count(distinct i->>'line_id')from jsonb_array_elements(p_payload->'items')i)then raise exception'KEEL_INVALID_COMMAND: every statement line requires one explanation'using errcode='P0009';end if;
 if exists(select 1 from jsonb_array_elements(p_payload->'items')i where (i-'line_id'-'resolution'-'transaction_id'-'explanation')<>'{}'::jsonb or coalesce(i->>'line_id','')!~'^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'or coalesce(i->>'resolution','')not in('matched_transaction','stale_balance','missing_event','duplicate','pending_posting','opening_balance','adjustment')or length(coalesce(i->>'explanation',''))not between 1 and 500 or(i->>'resolution'='matched_transaction'and coalesce(i->>'transaction_id','')!~'^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$')or(i->>'resolution'<>'matched_transaction'and i?'transaction_id'))or exists(select 1 from jsonb_array_elements(p_payload->'adjustments')a where(a-'kind'-'amount_minor'-'explanation')<>'{}'::jsonb or coalesce(a->>'kind','')not in('stale_balance','missing_event','duplicate','pending_posting','opening_balance','adjustment')or coalesce(a->>'amount_minor','')!~'^-?(0|[1-9][0-9]*)$'or a->>'amount_minor'='-0'or length(coalesce(a->>'explanation',''))not between 1 and 500)then raise exception'KEEL_INVALID_COMMAND: invalid reconciliation evidence'using errcode='P0009';end if;
 begin select a.entity_id,coalesce((select sum(jp.amount_minor)from public.journal_postings jp join public.journal_batches jb on jb.id=jp.batch_id where jp.ledger_account_id=a.ledger_account_id and jp.currency=v_s.currency and jb.household_id=p_household_id and jb.effective_date<=v_s.period_end),0)::bigint into v_entity,v_ledger from public.accounts a where a.household_id=p_household_id and a.id=v_s.account_id;v_diff:=v_s.ending_minor-v_ledger;select coalesce(sum((x->>'amount_minor')::bigint),0)::bigint into v_adj from jsonb_array_elements(p_payload->'adjustments')x;exception when numeric_value_out_of_range then raise exception'KEEL_INVALID_COMMAND: reconciliation arithmetic overflow'using errcode='P0009';end;if v_adj<>v_diff then raise exception'KEEL_INVALID_COMMAND: ledger difference unexplained'using errcode='P0009';end if;
 insert into public.period_locks(household_id,entity_id,start_date,end_date,locked_by)values(p_household_id,v_entity,v_s.period_start,v_s.period_end,(v_actor->>'userId')::uuid)returning id into v_lock;insert into public.reconciliation_sessions(household_id,id,statement_id,account_id,ledger_ending_minor,difference_minor,status,formula_version,period_lock_id,closed_by,closed_at)values(p_household_id,v_session,v_s.id,v_s.account_id,v_ledger,v_diff,'closed','statement-close-v1',v_lock,(v_actor->>'userId')::uuid,now());
 for v_item in select value from jsonb_array_elements(p_payload->'items')loop if not exists(select 1 from public.statement_lines l where l.household_id=p_household_id and l.statement_id=v_s.id and l.id=(v_item->>'line_id')::uuid)then raise exception'KEEL_SCOPE_VIOLATION: statement line not found'using errcode='P0006';end if;if v_item->>'resolution'='matched_transaction'and not exists(select 1 from public.canonical_transactions t where t.household_id=p_household_id and t.account_id=v_s.account_id and t.id=(v_item->>'transaction_id')::uuid and t.effective_date between v_s.period_start and v_s.period_end and t.status in('posted','reviewed')and t.voided_at is null)then raise exception'KEEL_SCOPE_VIOLATION: matched transaction not found'using errcode='P0006';end if;insert into public.reconciliation_items(household_id,session_id,statement_line_id,resolution,transaction_id,explanation)values(p_household_id,v_session,(v_item->>'line_id')::uuid,(v_item->>'resolution')::public.reconciliation_resolution,nullif(v_item->>'transaction_id','')::uuid,v_item->>'explanation');end loop;
 for v_row in select value from jsonb_array_elements(p_payload->'adjustments')loop insert into public.reconciliation_adjustments(household_id,session_id,kind,amount_minor,explanation)values(p_household_id,v_session,(v_row->>'kind')::public.reconciliation_resolution,(v_row->>'amount_minor')::bigint,v_row->>'explanation');end loop;insert into public.close_checklists(household_id,session_id,checklist_version,checks)values(p_household_id,v_session,'statement-close-v1',jsonb_build_object('allLinesExplained',true,'differenceExplained',true,'historyLocked',true));insert into public.reconciliation_status_events(household_id,session_id,transition,actor,command_id)values(p_household_id,v_session,'closed',v_actor,p_command_id);
 v_after:=jsonb_build_object('sessionId',v_session,'statementId',v_s.id,'status','closed','ledgerEndingMinor',v_ledger::text,'statementEndingMinor',v_s.ending_minor::text,'differenceMinor',v_diff::text,'periodLockId',v_lock);v_result:=jsonb_build_object('commandId',p_command_id,'economicEventKey',p_economic_event_key,'idempotentReplay',false,'effects',v_after,'asOf',to_char(now()at time zone'utc','YYYY-MM-DD"T"HH24:MI:SS"Z"'));perform public.keel_finish_command(p_command_id,'reconciliations.close',p_economic_event_key,p_household_id,v_actor,v_hash,'reconciliations.closed','reconciliation_session',v_session,v_after,v_result);return v_result;
end;$$;
create function public.keel_reconciliation_reopen(p_command_id uuid,p_economic_event_key text,p_actor jsonb,p_household_id uuid,p_payload jsonb)returns jsonb language plpgsql security definer set search_path=public as $$
declare v_hash text:=public.keel_payload_hash(p_payload);v_replay jsonb;v_actor jsonb;v_s public.reconciliation_sessions%rowtype;v_before jsonb;v_after jsonb;v_result jsonb;
begin perform public.keel_assert_member_write(p_household_id);v_actor:=public.keel_actor_from_jwt();v_replay:=public.keel_idempotency_check(p_household_id,p_economic_event_key,v_hash);if v_replay is not null then return v_replay;end if;
 if jsonb_typeof(p_payload)<>'object'or(p_payload-'session_id'-'reason')<>'{}'::jsonb or length(coalesce(p_payload->>'reason',''))not between 1 and 500 then raise exception'KEEL_INVALID_COMMAND: malformed reopen'using errcode='P0009';end if;
 begin select*into v_s from public.reconciliation_sessions where household_id=p_household_id and id=(p_payload->>'session_id')::uuid for update;exception when invalid_text_representation then raise exception'KEEL_INVALID_COMMAND: invalid session id'using errcode='P0009';end;
 if not found or v_s.status<>'closed'or not public.keel_statement_access(p_household_id,v_s.statement_id,true)then raise exception'KEEL_SCOPE_VIOLATION: closed session not found'using errcode='P0006';end if;
 v_before:=jsonb_build_object('sessionId',v_s.id,'status','closed');update public.period_locks set reopened_at=now(),reopen_reason=p_payload->>'reason'where household_id=p_household_id and id=v_s.period_lock_id and reopened_at is null;if not found then raise exception'KEEL_SCOPE_VIOLATION: active period lock not found'using errcode='P0006';end if;update public.reconciliation_sessions set status='reopened',reopened_at=now()where household_id=p_household_id and id=v_s.id;insert into public.reconciliation_status_events(household_id,session_id,transition,reason,actor,command_id)values(p_household_id,v_s.id,'reopened',p_payload->>'reason',v_actor,p_command_id);v_after:=jsonb_build_object('sessionId',v_s.id,'status','reopened','reason',p_payload->>'reason');v_result:=jsonb_build_object('commandId',p_command_id,'economicEventKey',p_economic_event_key,'idempotentReplay',false,'effects',v_after,'asOf',to_char(now()at time zone'utc','YYYY-MM-DD"T"HH24:MI:SS"Z"'));insert into public.audit_log(household_id,actor,action,object_type,object_id,command_id,before,after)values(p_household_id,v_actor,'reconciliations.reopen','reconciliation_session',v_s.id,p_command_id,v_before,v_after);insert into public.domain_events(event_type,household_id,command_id,economic_event_key,actor,payload)values('reconciliations.reopened',p_household_id,p_command_id,p_economic_event_key,v_actor,v_after);insert into public.command_executions(household_id,economic_event_key,command_id,command,payload_sha256,result)values(p_household_id,p_economic_event_key,p_command_id,'reconciliations.reopen',v_hash,v_result);return v_result;
end;$$;
create function public.keel_list_statements(p_household_id uuid)returns jsonb language plpgsql security definer stable set search_path=public as $$declare v_uid uuid:=coalesce(nullif(pg_catalog.current_setting('request.jwt.claim.sub',true),''),nullif(pg_catalog.current_setting('request.jwt.claims',true),'')::jsonb->>'sub')::uuid;v_rows jsonb;begin if not exists(select 1 from public.household_memberships where household_id=p_household_id and user_id=v_uid)then raise exception'KEEL_SCOPE_VIOLATION'using errcode='P0006';end if;select coalesce(jsonb_agg(jsonb_build_object('statementId',s.id,'accountId',s.account_id,'periodStart',to_char(s.period_start,'YYYY-MM-DD'),'periodEnd',to_char(s.period_end,'YYYY-MM-DD'),'openingMinor',s.opening_minor::text,'endingMinor',s.ending_minor::text,'currency',s.currency::text,'sourceHash',s.source_hash,'status',coalesce((select r.status::text from public.reconciliation_sessions r where r.household_id=s.household_id and r.statement_id=s.id),'open'),'lines',(select jsonb_agg(jsonb_build_object('lineId',l.id,'lineKey',l.line_key,'date',to_char(l.line_date,'YYYY-MM-DD'),'amountMinor',l.amount_minor::text,'description',l.description)order by l.line_date,l.id)from public.statement_lines l where l.household_id=s.household_id and l.statement_id=s.id),'session',(select jsonb_build_object('sessionId',r.id,'ledgerEndingMinor',r.ledger_ending_minor::text,'differenceMinor',r.difference_minor::text,'status',r.status,'formulaVersion',r.formula_version,'periodLockId',r.period_lock_id,'closedAt',to_char(r.closed_at at time zone'utc','YYYY-MM-DD"T"HH24:MI:SS"Z"'),'reopenedAt',case when r.reopened_at is null then null else to_char(r.reopened_at at time zone'utc','YYYY-MM-DD"T"HH24:MI:SS"Z"')end,'items',coalesce((select jsonb_agg(jsonb_build_object('lineId',i.statement_line_id,'resolution',i.resolution,'transactionId',i.transaction_id,'explanation',i.explanation)order by i.id)from public.reconciliation_items i where i.household_id=r.household_id and i.session_id=r.id),'[]'::jsonb),'adjustments',coalesce((select jsonb_agg(jsonb_build_object('kind',a.kind,'amountMinor',a.amount_minor::text,'explanation',a.explanation)order by a.id)from public.reconciliation_adjustments a where a.household_id=r.household_id and a.session_id=r.id),'[]'::jsonb),'checklist',(select c.checks from public.close_checklists c where c.household_id=r.household_id and c.session_id=r.id))from public.reconciliation_sessions r where r.household_id=s.household_id and r.statement_id=s.id))order by s.period_end,s.id),'[]'::jsonb)into v_rows from public.statements s where s.household_id=p_household_id and public.keel_recurring_account_access(p_household_id,s.account_id,false);return jsonb_build_object('scope',jsonb_build_object('householdId',p_household_id),'asOf',to_char(now()at time zone'utc','YYYY-MM-DD"T"HH24:MI:SS"Z"'),'formulaVersion','statement-close-v1','rows',v_rows);end;$$;
alter table public.statements enable row level security;alter table public.statement_lines enable row level security;alter table public.reconciliation_sessions enable row level security;alter table public.reconciliation_items enable row level security;alter table public.reconciliation_adjustments enable row level security;alter table public.close_checklists enable row level security;alter table public.reconciliation_status_events enable row level security;revoke all on public.statements,public.statement_lines,public.reconciliation_sessions,public.reconciliation_items,public.reconciliation_adjustments,public.close_checklists,public.reconciliation_status_events from public,anon,authenticated;grant select on public.statements,public.statement_lines,public.reconciliation_sessions,public.reconciliation_items,public.reconciliation_adjustments,public.close_checklists,public.reconciliation_status_events to authenticated,service_role;
create policy statements_read on public.statements for select to authenticated using(public.keel_recurring_account_access(household_id,account_id,false));create policy statement_lines_read on public.statement_lines for select to authenticated using(public.keel_statement_access(household_id,statement_id,false));create policy sessions_read on public.reconciliation_sessions for select to authenticated using(public.keel_statement_access(household_id,statement_id,false));create policy items_read on public.reconciliation_items for select to authenticated using(exists(select 1 from public.reconciliation_sessions s where s.household_id=reconciliation_items.household_id and s.id=reconciliation_items.session_id and public.keel_statement_access(s.household_id,s.statement_id,false)));create policy adjustments_read on public.reconciliation_adjustments for select to authenticated using(exists(select 1 from public.reconciliation_sessions s where s.household_id=reconciliation_adjustments.household_id and s.id=reconciliation_adjustments.session_id and public.keel_statement_access(s.household_id,s.statement_id,false)));create policy checklists_read on public.close_checklists for select to authenticated using(exists(select 1 from public.reconciliation_sessions s where s.household_id=close_checklists.household_id and s.id=close_checklists.session_id and public.keel_statement_access(s.household_id,s.statement_id,false)));create policy reconciliation_events_read on public.reconciliation_status_events for select to authenticated using(exists(select 1 from public.reconciliation_sessions s where s.household_id=reconciliation_status_events.household_id and s.id=reconciliation_status_events.session_id and public.keel_statement_access(s.household_id,s.statement_id,false)));
grant select,insert on public.statements to keel_api;grant select,insert,update on public.reconciliation_sessions to keel_api;grant select,insert on public.statement_lines,public.reconciliation_items,public.reconciliation_adjustments,public.close_checklists,public.reconciliation_status_events to keel_api;create policy statements_api on public.statements for all to keel_api using(true)with check(true);create policy lines_api on public.statement_lines for all to keel_api using(true)with check(true);create policy sessions_api on public.reconciliation_sessions for all to keel_api using(true)with check(true);create policy items_api on public.reconciliation_items for all to keel_api using(true)with check(true);create policy adjustments_api on public.reconciliation_adjustments for all to keel_api using(true)with check(true);create policy checklists_api on public.close_checklists for all to keel_api using(true)with check(true);create policy reconciliation_events_api on public.reconciliation_status_events for all to keel_api using(true)with check(true);
grant create on schema public to keel_api;alter function public.keel_statement_access(uuid,uuid,boolean)owner to keel_api;alter function public.keel_statement_create(uuid,text,jsonb,uuid,jsonb)owner to keel_api;alter function public.keel_reconciliation_close(uuid,text,jsonb,uuid,jsonb)owner to keel_api;alter function public.keel_reconciliation_reopen(uuid,text,jsonb,uuid,jsonb)owner to keel_api;alter function public.keel_list_statements(uuid)owner to keel_api;revoke create on schema public from keel_api;revoke all on function public.keel_statement_access(uuid,uuid,boolean)from public,anon,authenticated;grant execute on function public.keel_statement_access(uuid,uuid,boolean)to authenticated,keel_api;revoke all on function public.keel_statement_create(uuid,text,jsonb,uuid,jsonb),public.keel_reconciliation_close(uuid,text,jsonb,uuid,jsonb),public.keel_reconciliation_reopen(uuid,text,jsonb,uuid,jsonb),public.keel_list_statements(uuid)from public,anon;grant execute on function public.keel_statement_create(uuid,text,jsonb,uuid,jsonb),public.keel_reconciliation_close(uuid,text,jsonb,uuid,jsonb),public.keel_reconciliation_reopen(uuid,text,jsonb,uuid,jsonb),public.keel_list_statements(uuid)to authenticated;
do $$begin if exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace join pg_roles r on r.oid=p.proowner where n.nspname='public'and(p.proname like'keel%statement%'or p.proname like'keel%reconciliation%')and p.prosecdef and r.rolname<>'keel_api')then raise exception'KEEL_OWNERSHIP: reconciliation owner';end if;if not exists(select 1 from pg_roles where rolname='keel_api'and rolcanlogin=false and rolsuper=false and rolbypassrls=false)then raise exception'KEEL_OWNERSHIP: invalid keel_api role';end if;end$$;
grant select on public.statements,public.statement_lines,public.reconciliation_sessions,public.reconciliation_items,public.reconciliation_adjustments,public.close_checklists,public.reconciliation_status_events to keel_export;create policy statements_export on public.statements for select to keel_export using(true);create policy lines_export on public.statement_lines for select to keel_export using(true);create policy sessions_export on public.reconciliation_sessions for select to keel_export using(true);create policy items_export on public.reconciliation_items for select to keel_export using(true);create policy adjustments_export on public.reconciliation_adjustments for select to keel_export using(true);create policy checklists_export on public.close_checklists for select to keel_export using(true);create policy reconciliation_events_export on public.reconciliation_status_events for select to keel_export using(true);
alter function public.keel_export_household(uuid,timestamptz)rename to keel_export_household_pre_reconciliation;revoke all on function public.keel_export_household_pre_reconciliation(uuid,timestamptz)from public,anon,authenticated,service_role;create function public.keel_export_household(p_household_id uuid,p_as_of timestamptz default null)returns jsonb language plpgsql security definer stable set search_path=pg_catalog,public as $$declare v_base jsonb;v_tables jsonb;begin v_base:=public.keel_export_household_pre_reconciliation(p_household_id,p_as_of);select jsonb_build_object('statements',coalesce((select jsonb_agg(to_jsonb(x)||jsonb_build_object('opening_minor',x.opening_minor::text,'ending_minor',x.ending_minor::text)order by x.id)from public.statements x where x.household_id=p_household_id),'[]'::jsonb),'statement_lines',coalesce((select jsonb_agg(to_jsonb(x)||jsonb_build_object('amount_minor',x.amount_minor::text)order by x.household_id,x.id)from public.statement_lines x where x.household_id=p_household_id),'[]'::jsonb),'reconciliation_sessions',coalesce((select jsonb_agg(to_jsonb(x)||jsonb_build_object('ledger_ending_minor',x.ledger_ending_minor::text,'difference_minor',x.difference_minor::text)order by x.household_id,x.id)from public.reconciliation_sessions x where x.household_id=p_household_id),'[]'::jsonb),'reconciliation_items',coalesce((select jsonb_agg(to_jsonb(x)order by x.household_id,x.id)from public.reconciliation_items x where x.household_id=p_household_id),'[]'::jsonb),'reconciliation_adjustments',coalesce((select jsonb_agg(to_jsonb(x)||jsonb_build_object('amount_minor',x.amount_minor::text)order by x.household_id,x.id)from public.reconciliation_adjustments x where x.household_id=p_household_id),'[]'::jsonb),'close_checklists',coalesce((select jsonb_agg(to_jsonb(x)order by x.household_id,x.id)from public.close_checklists x where x.household_id=p_household_id),'[]'::jsonb),'reconciliation_status_events',coalesce((select jsonb_agg(to_jsonb(x)order by x.household_id,x.id)from public.reconciliation_status_events x where x.household_id=p_household_id),'[]'::jsonb))into v_tables;return jsonb_set(v_base,'{tables}',v_base->'tables'||v_tables);end$$;revoke all on function public.keel_export_household(uuid,timestamptz)from public,anon,authenticated,service_role;grant create on schema public to keel_export;alter function public.keel_export_household(uuid,timestamptz)owner to keel_export;revoke create on schema public from keel_export;grant execute on function public.keel_export_household(uuid,timestamptz)to service_role;
